window.AULAS["aula-06-1"] = {"id": "aula-06-1", "titulo": "Aula 6.1 - Semiologia tegumentar", "subtitulo": "Pele, mucosas, cabelos e unhas: observar, palpar, descrever e contextualizar", "pdf": "pdf/aula-06-1.pdf", "fontes": ["Porto, Semiologia Médica (8ª ed.)", "Bates, Propedêutica Médica (12ª ed.)", "Atlas fotográfico de dermatologia (000PM02), uso educacional", "Aula 6.1 (slides do Prof. Dr. João Vítor Galo Esteves)"], "resumo": [{"titulo": "1. Abertura e método (slides 1 a 6)", "pontos": [{"t": "Objetivos (slide 5)", "sub": ["Examinar com método: luz, exposição e sequência fixa.", "Nomear a lesão predominante, usando o vocabulário das lesões elementares.", "Descrever distribuição e evolução: onde, como se arranja e como mudou.", "Reconhecer alertas: o que muda a prioridade clínica."]}, {"t": "Regra de ouro (slide 5)", "sub": ["Descreva antes de nomear.", "Lesões agrupadas em faixa unilateral pedem descrição do padrão antes de qualquer nome de doença.", "Uma descrição correta é útil mesmo quando o diagnóstico permanece aberto."]}, {"t": "Anamnese tegumentar dirigida (slide 6)", "sub": ["Quando começou? Como mudou? (surgimento, extensão e mudança).", "Prurido, dor, ardor ou febre?", "Novos medicamentos, produtos, sol ou contatos? (pergunta-chave em eritema de antebraços: contato com produto).", "Impacto no sono, na rotina e na preocupação da pessoa."]}]}, {"titulo": "2. Método, gatilho clínico e competências (slides 2 a 4)", "pontos": [{"t": "O método (slide 2)", "sub": ["Observar, palpar, descrever e contextualizar; pele, mucosas, cabelos e unhas.", "Não antecipe diagnósticos: siga o fluxo clínico estruturado.", "O exame fornece dados locais e sinais de doenças sistêmicas; o objetivo é uma descrição morfológica reprodutível.", "Erro: saltar da imagem direto para o diagnóstico, sem palpar a lesão nem contextualizar com a história."]}, {"t": "Gatilho clínico: manchas nas pernas e febre (slide 3)", "sub": ["O termo leigo 'mancha' é inespecífico e agrupa mecanismos vascular (eritema, isquemia), pigmentar (melanina, hemossiderina) e inflamatório (infiltração, edema).", "Febre associada a novas lesões cutâneas agudas muda a prioridade do atendimento: excluir infecção grave ou vasculite."]}, {"t": "Competências do exame (slide 4)", "sub": ["Examinar com método: técnica, iluminação oblíqua adequada e sequência anatômica.", "Nomear a lesão predominante: diferenciar relevo e conteúdo e identificar a lesão primária.", "Descrever e distribuir: medidas, evolução, padrões geométricos e topografia.", "Reconhecer alertas: sinais de gravidade tegumentar e sistêmica."]}]}, {"titulo": "3. Anamnese, logística e métodos (slides 7 a 9)", "pontos": [{"t": "Anamnese: a linha do tempo da lesão (slide 7)", "sub": ["Início: quando e onde surgiu a primeira lesão.", "Evolução: como mudou; houve disseminação ou recorrência.", "Sintomas: prurido (antes ou depois de surgir a lesão), dor, ardor, sintomas sistêmicos (febre, astenia).", "Exposições: fármacos, cosméticos, sol, viagens, contatos.", "Impacto: sono, rotina ou preocupação estética.", "A história rigorosa refina e restringe as hipóteses antes mesmo da inspeção."]}, {"t": "Logística e percurso do exame (slide 8)", "sub": ["Luz branca, de preferência natural, com incidência oblíqua para evidenciar o relevo.", "Privacidade total e consentimento contínuo; exposição seletiva, desnudando só a região examinada.", "Percurso: cabeça, tronco, membros, mãos e pés, dorso.", "Áreas negligenciadas: couro cabeludo, mucosas acessíveis, interdigitações, plantas dos pés e leito ungueal."]}, {"t": "Métodos: olhar e tocar (slide 9)", "sub": ["Inspeção responde: cor predominante, forma e configuração geométrica, extensão e limites, superfície visível.", "Palpação responde: temperatura local (comparativa), úmido ou seco, espessura, turgor e consistência, mobilidade ou aderência e dor ao toque.", "Erro: presumir o relevo apenas pela visão; a distinção mácula (plana) e pápula (elevada) exige confirmação tátil."]}]}, {"titulo": "4. Inspeção, palpação e pele geral (slides 10 a 14)", "pontos": [{"t": "Inspeção e palpação respondem perguntas diferentes (slide 10)", "sub": ["Inspeção: cor, forma, extensão e superfície.", "Palpação: temperatura, umidade, espessura, consistência, mobilidade e dor.", "Mácula ou pápula? Só o tato confirma se há elevação."]}, {"t": "Cor e circulação (slide 12)", "sub": ["Compare com o tom basal e descreva a alteração em relação a ele.", "Palidez: comparar mão pálida com a normal.", "Eritema: comparar um pé com o outro.", "Cianose central: lábios, face e extremidades.", "Cianose periférica: leitos ungueais.", "Icterícia: observar a esclera, sobretudo em pele negra, onde a pele pode mascarar a cor."]}, {"t": "Propriedades palpáveis (slide 14)", "sub": ["Umidade e temperatura (extremidades mais frias são um achado comum).", "Textura, espessura e mobilidade.", "Elasticidade e turgor: prega cutânea pinçada e solta; uma prega que persiste deve ser lida no contexto.", "Descreva se o achado é localizado ou generalizado, e compare regiões homólogas."]}]}, {"titulo": "5. Cor, perfusão e técnica do toque (slides 13 e 15)", "pontos": [{"t": "Análise de cor e perfusão (slide 13)", "sub": ["Avalie toda alteração em relação ao tom basal do indivíduo.", "Palidez: redução do fluxo ou isquemia; áreas-chave: palmas, plantas, leito ungueal e conjuntivas.", "Eritema: vasodilatação ou inflamação; tom avermelhado, com calor local.", "Cianose: hipóxia (hemoglobina reduzida acima de 5 g/dL); lábios e extremidades distais.", "Icterícia: acúmulo de bilirrubina; esclera e freio da língua.", "Alerta: em peles melanodérmicas, palidez e cianose podem ser mascaradas; o exame das mucosas acessíveis é mandatório."]}, {"t": "Propriedades palpáveis: técnica do toque (slide 15)", "sub": ["Temperatura: dorso das mãos ou dos dedos, em regiões homólogas.", "Textura e espessura: polpas digitais; classificar como normal, áspera, atrófica (fina) ou hipertrófica (espessa).", "Elasticidade e turgor: pinçar pele e tecido celular subcutâneo e observar a velocidade de retorno da prega.", "Erro: assumir que turgor diminuído, isoladamente, confirma desidratação; idade (elastose) e local da prega modificam a interpretação."]}]}, {"titulo": "6. Frase morfológica e distribuição (slides 16 e 18)", "pontos": [{"t": "Frase morfológica (slide 16): nessa ordem", "sub": ["Número.", "Lesão predominante.", "Medida (com régua, em milímetros).", "Cor.", "Forma e limites.", "Superfície.", "Localização e distribuição.", "Exemplo: placa única, eritematosa, anular, de limites nítidos e borda descamativa, no dorso do punho."]}, {"t": "Distribuição e arranjo (slide 18)", "sub": ["Localizada ou disseminada; simétrica ou assimétrica.", "Arranjo: linear, anular, agrupado, reticular ou dermatomérico.", "Onde? Áreas fotoexpostas, flexuras, extremidades ou dermátomo.", "Vesículas agrupadas em faixa unilateral comunicam mais do que o nome de uma doença presumida."]}]}, {"titulo": "7. Distribuição, relevo e algoritmo morfológico (slides 19 a 22 e 24)", "pontos": [{"t": "Distribuição topográfica e arranjo geométrico (slide 19)", "sub": ["Distribuição: extensão (localizada, generalizada, universal), simetria e áreas preferenciais (fotoexpostas, extensoras ou flexoras, pregas intertriginosas).", "Arranjo: linear (trauma por coçadura), anular (anel com centro claro), agrupado ou herpetiforme, zosteriforme (trajeto nervoso).", "A localização exata ajuda a diferenciar mecanismo externo (dermatite de contato) de manifestação sistêmica endógena."]}, {"t": "A primeira decisão: relevo e conteúdo (slides 21 e 22)", "sub": ["Avaliação tátil: mesmo plano (lesão plana), elevada (sólida, edematosa ou líquida) ou deprimida (perda de superfície ou tecido).", "Planas: máculas e manchas. Elevadas sólidas: pápula, nódulo, placa. Líquidas: vesícula, bolha. Perda tecidual: erosão (epiderme) e úlcera (derme ou profunda).", "Teste da compressão (vitropressão): eritema vascular empalidece; extravasamento hemorrágico (púrpura) não empalidece.", "Erro comum: inferir o diagnóstico pela cor antes de palpar o relevo."]}, {"t": "Lesões planas: mácula e mancha (slide 24)", "sub": ["Definição: mudança circunscrita de cor, sem elevação ou depressão palpável.", "Mácula: pequena (geralmente menor que 1 cm). Mancha: extensa (geralmente maior que 1 cm).", "Parâmetros: cor exata, medida (mm ou cm), bordas e distribuição.", "A nomenclatura do tamanho limítrofe varia entre Porto e Bates versus Rocco; registre a medida real."]}]}, {"titulo": "8. Primeira decisão: relevo e conteúdo (slide 22)", "pontos": [{"t": "Pergunta-chave", "sub": ["Mesmo plano da pele? Então a lesão é plana.", "Elevada? Verifique se é sólida, edematosa ou líquida.", "Há perda de superfície ou de tecido?", "Procure a lesão predominante e as diferentes fases presentes."]}]}, {"titulo": "9. Lesões planas: mácula, eritema, púrpura (slides 25 e 26)", "pontos": [{"t": "Mácula ou mancha (slide 25)", "sub": ["Mudança circunscrita de cor.", "Sem elevação nem depressão palpável.", "Tipos: eritematosa; vascular (telangiectasias); hipercrômica (mais escura); hipo ou acrômica (mais clara).", "Descreva cor, medida, bordas e distribuição."]}, {"t": "Compressão: eritema ou púrpura? (slide 26)", "sub": ["Vitropressão: lâmina de vidro sobre a pele.", "Eritema: vasodilatação; empalidece à compressão.", "Púrpura: extravasamento sanguíneo; não empalidece.", "Dentro da púrpura: petéquia (pequena, puntiforme), víbice (linear) e equimose.", "Registre extensão, contexto e sintomas."]}]}, {"titulo": "10. Lesões sólidas, urtica e conteúdo líquido (slides 28, 30 e 32)", "pontos": [{"t": "Lesões sólidas elevadas: perfis de profundidade (slide 28)", "sub": ["Pápula: pequena elevação (menor que 1 cm), em epiderme e derme papilar.", "Placa: elevação com extensão horizontal maior que a altura, frequentemente por confluência de pápulas.", "Nódulo ou nodosidade: componente palpável profundo (derme profunda ou subcutâneo), frequentemente mais palpável que visível.", "Descrever tamanho, consistência, mobilidade, superfície e dor importa mais que fronteiras rígidas de nomenclatura."]}, {"t": "Elevação edematosa: urtica (slide 30)", "sub": ["Elevação por extravasamento agudo de plasma (edema dérmico), intensamente pruriginosa.", "Lesões individuais surgem e desaparecem em menos de 24 horas, sem deixar marcas.", "Red flag: angioedema (vias respiratórias superiores, lábios ou língua) e progressão para anafilaxia mudam a prioridade para emergência; lesões fixas (mais de 24 horas) ou dolorosas exigem reavaliação diagnóstica."]}, {"t": "Lesões de conteúdo líquido (slide 32)", "sub": ["Vesícula: conteúdo seroso, diâmetro até 1 cm (Porto e Bates) ou 0,5 cm (Rocco).", "Bolha: coleção líquida grande, maior que 1 cm (ou 0,5 cm).", "Pústula: elevação circunscrita com exsudato purulento.", "Erro comum: assumir que toda pústula indica infecção bacteriana ativa; condições imunes (psoríase pustulosa) também geram conteúdo purulento estéril. Considere agrupamento e base inflamatória."]}]}, {"titulo": "11. Lesões elevadas (slides 29 e 31)", "pontos": [{"t": "Lesões sólidas (slide 29)", "sub": ["Pápula: pequena elevação sólida, infiltrada na derme.", "Placa: elevação com extensão horizontal; pode ser descamativa.", "Nódulo: componente palpável mais profundo, na derme profunda.", "Palpe tamanho, consistência, mobilidade, superfície e dor."]}, {"t": "Urtica e edema (slide 31)", "sub": ["Elevação por edema, geralmente pruriginosa.", "Observe a duração de cada lesão.", "Dermografismo: urticas após atrito.", "Angioedema facial: lábios ou língua inchados e falta de ar mudam a prioridade."]}]}, {"titulo": "12. Conteúdo líquido, superfície e perda de tecido (slides 33 a 39)", "pontos": [{"t": "Conteúdo líquido (slide 33)", "sub": ["Vesícula: líquido claro, pequeno.", "Bolha: coleção líquida maior.", "Pústula: conteúdo amarelo-esbranquiçado ou purulento, sobre base eritematosa.", "Considere tamanho, agrupamento e base inflamatória. Registre a medida em milímetros, porque o limiar vesícula/bolha varia entre os livros."]}, {"t": "Superfície (slide 35)", "sub": ["Escama: desprendimento da camada córnea, em lâminas secas e finas.", "Crosta: exsudato ressecado aderido. Crosta melicérica: amarelada.", "Descreva espessura, cor, aderência e extensão."]}, {"t": "Perda tecidual (slide 37)", "sub": ["Erosão: perda superficial, só epiderme.", "Úlcera: perda que alcança a derme.", "Fissura: solução de continuidade linear, em fenda."]}, {"t": "Alterações adicionais (slide 39)", "sub": ["Escoriação: trauma ou coçadura.", "Liquenificação: espessamento com linhas acentuadas.", "Cicatriz: reparo com tecido fibroso.", "Atrofia: pele fina e pregueada.", "Pergunte se a alteração é primária ou secundária: uma lesão pode evoluir."]}]}, {"titulo": "13. Superfície, perda tecidual e alterações adicionais (slides 34, 36 e 38)", "pontos": [{"t": "Alterações secundárias: superfície (slide 34)", "sub": ["Escama: desprendimento anômalo do estrato córneo; fina e seca (micoses) ou grossa e prateada (psoríase).", "Crosta: ressecamento de exsudato prévio (soro, sangue ou pus) sobre a pele.", "São lesões secundárias por excelência: indicam a modificação temporal de uma lesão primária (bolha que rompe gera crosta; pápula inflamatória evolui para descamação)."]}, {"t": "Perda tecidual: profundidades (slide 36)", "sub": ["Erosão (exulceração): perda restrita à epiderme; cicatriza sem marca estrutural.", "Úlcera: perda que ultrapassa a membrana basal, atingindo derme ou subcutâneo; deixa cicatriz fibrosa.", "Fissura: fenda linear, estreita e profunda, geralmente com dor focal.", "Descrever bordas, leito (necrose, granulação), profundidade estimada e natureza do exsudato."]}, {"t": "Alterações adicionais: evolução e reparo (slide 38)", "sub": ["Escoriação: traumatismo linear exógeno, indicativo do ato de coçar.", "Liquenificação: espessamento reativo com acentuação grosseira dos sulcos (aspecto quadriculado); registro de coçadura crônica.", "Atrofia: afinamento visível com perda de elasticidade e pregueamento anômalo.", "Cicatriz: reposição definitiva por tecido conjuntivo fibrótico após dano dérmico profundo."]}]}, {"titulo": "14. Anexos e áreas frequentemente omitidas (slides 40 a 46)", "pontos": [{"t": "Cabelos e couro cabeludo (slide 42)", "sub": ["Distribuição difusa ou em placas.", "Rarefação em placa: área redonda sem fios.", "Rarefação difusa: região frontal.", "Couro cabeludo: eritema, descamação espessa, pústulas, cicatriz, placas retroauriculares.", "Fio: queda pela raiz ou quebra da haste."]}, {"t": "Unhas (slide 44): inspecione as dez, quando possível", "sub": ["Lâmina, leito e pregas.", "Cor, forma, espessura e aderência.", "Faixa pigmentada longitudinal.", "Mancha branca na lâmina.", "Lâmina espessada e descolada.", "Superfície irregular em várias unhas.", "Lâmina estriada e afinada.", "Compare mãos e pés."]}, {"t": "Mucosas e regiões omitidas (slide 46)", "sub": ["Conjuntiva palpebral.", "Lábios e língua (cavidade oral acessível).", "Palmas e plantas.", "Espaços interdigitais e dorso.", "Adeque o exame à queixa e ao consentimento."]}]}, {"titulo": "15. Cabelos, unhas e mucosas: achados dos slides ilustrados (slides 41, 43 e 45)", "pontos": [{"t": "Cabelos e couro cabeludo (slide 41)", "sub": ["Padrão da perda pilosa: difusa global versus localizada (alopecia areata).", "Haste: avaliar quebra, variação de espessura e brilho.", "Couro cabeludo: descamação (dermatite seborreica), pústulas foliculares, cicatrizes e eritema basal.", "Red flag: alopecia cicatricial (perda definitiva dos óstios foliculares) indica destruição irreparável do folículo e exige diagnóstico precoce."]}, {"t": "Avaliação ungueal: estruturas e checkpoints (slide 43)", "sub": ["Compare simetria entre mãos e pés.", "Lâmina ungueal: cor, forma e espessura; linhas de Beau indicam interrupção sistêmica do crescimento.", "Leito ungueal: perfusão capilar e opacidade sistêmica; unhas de Terry (cirrose, hipoalbuminemia) e unhas de Lindsay (uremia).", "Pregas: edema, inflamação ou pigmentação.", "Dica: faixas pigmentadas novas ou em mudança exigem avaliação; não atribua toda alteração ungueal a trauma ou onicomicose."]}, {"t": "Checklist anatômico: mucosas e áreas ocultas (slide 45)", "sub": ["Polo cefálico: conjuntivas (palidez, icterícia); lábios e cavidade oral (lesões ulceronecróticas, pigmentação palatina).", "Extremidades: palmas, plantas e espaços interdigitais (focos ocultos de tinea e infecção).", "Dorso e pregas: áreas de difícil autoexame.", "Conduta ética: adequar a extensão do exame à queixa, explicar o procedimento e obter consentimento explícito antes de inspecionar áreas íntimas."]}]}, {"titulo": "16. ABCDE e sinais de alerta ilustrados (slides 48, 50 a 52, 54 e 56)", "pontos": [{"t": "Regra ABCDE ilustrada (slides 48 e 50)", "sub": ["A, assimetria: metades que não coincidem. B, bordas: limites irregulares, entalhados ou mal definidos. C, cores: duas ou mais tonalidades. D, diâmetro: tradicionalmente suspeito acima de 6 mm. E, evolução: mudança rápida recente.", "O ABCDE organiza a suspeição clínica para triagem do melanoma; qualquer lesão 'patinho feio', que destoa do padrão basal do paciente, exige encaminhamento ou biópsia.", "Red flag: a evolução (E) é o critério mais sensível; mudança documentada exige investigação, mesmo em lesões menores que 6 mm."]}, {"t": "Síntese: sinais de alerta tegumentar (slides 51, 52 e 54)", "sub": ["Púrpura febril: petéquias ou equimoses não compressíveis com febre ou progressão rápida; risco de meningococcemia, sepse, vasculites agudas.", "Bolhas e mucosas: descolamento epidérmico extenso, dor cutânea ou acometimento oral ou conjuntival; risco de SSJ/NET.", "Dor intensa ou necrose: dor desproporcional ao achado visual, crepitação subcutânea ou necrose de bordas; risco de infecções necrosantes ou oclusão arterial.", "Evolução pigmentar: mudança rápida em nevo preexistente ou surgimento de lesão pigmentada irregular; risco de melanoma.", "O achado dermatológico nunca é isolado: não retarde a estabilização sistêmica para aprofundar a classificação morfológica."]}, {"t": "Diferenciação vascular: teste da compressão (slide 56)", "sub": ["Eritema (inflamação): vasodilatação; o sangue está dentro do vaso e o tecido empalidece à compressão.", "Púrpura (hemorragia): extravasamento capilar; o sangue está fora do vaso e a cor não se altera.", "Alerta: púrpura mais febre exige avaliação sistêmica imediata, pelo alto risco de meningococcemia, sepse grave ou vasculite."]}]}, {"titulo": "17. Alertas e prioridade (slides 49, 53 e 55)", "pontos": [{"t": "Lesão pigmentada em evolução: ABCDE (slide 49)", "sub": ["A: assimetria (metades diferentes).", "B: bordas irregulares ou entalhadas.", "C: cores variadas.", "D: diâmetro (referência de 6 mm).", "E: evolução.", "Referência do slide: pequenas, simétricas e de cor única tendem a ser menos suspeitas; A + B + C e B + C pedem atenção.", "A mudança importa, mesmo em lesões pequenas."]}, {"t": "Sinais de alerta tegumentares (slide 53)", "sub": ["Púrpura com febre ou progressão rápida: sinais vitais e estado geral; confirme com vitropressão; avaliação urgente.", "Bolhas extensas ou erosões com mucosas: examine boca, olhos e genitais; dimensione a extensão; avaliação urgente.", "Dor intensa, necrose ou comprometimento sistêmico: avaliação urgente.", "Dor desproporcional ao que se vê: sinais vitais e estado geral; avaliação urgente.", "Lesão pigmentada em evolução: meça e fotografe com escala; compare com as demais lesões; avaliação dirigida, sem tranquilizar pelo tamanho.", "Esses padrões mudam a prioridade e não são diagnósticos finais."]}, {"t": "Retorno ao caso: manchas e febre (slide 55)", "sub": ["Pernas: lesões planas avermelhadas, que não empalidecem.", "Febre e início recente.", "Petéquias puntiformes; púrpura em placas; máculas purpúricas.", "Descreva, examine o estado geral e priorize."]}]}, {"titulo": "18. Registro e checklist (slides 57, 60 e 62)", "pontos": [{"t": "Exercício (slide 57)", "sub": ["Lesão única, castanha, 8 mm, no dorso, de borda irregular, com aumento nos últimos meses.", "Tarefa: escreva uma frase morfológica e a prioridade."]}, {"t": "Modelo de registro (slide 60)", "sub": ["Localização.", "Morfologia.", "Medida.", "Cor e limites.", "Superfície (registrar se alterada).", "Distribuição.", "Sintomas e evolução.", "Exemplo: múltiplas pápulas eritematosas de 2 a 4 mm, agrupadas no antebraço direito, pruriginosas há 3 dias."]}, {"t": "Checklist de saída (slide 62)", "sub": ["1. História e contexto.", "2. Exame completo e respeitoso.", "3. Relevo e conteúdo (algoritmo: mesmo plano? elevada (sólida, edematosa ou líquida)? há perda de superfície ou tecido?).", "4. Medida, distribuição e evolução.", "5. Alertas e registro.", "Referências citadas no slide: Porto, Bates e Rocco."]}]}, {"titulo": "19. Registro e síntese final (slides 58, 59, 61 e 63)", "pontos": [{"t": "Síntese clínica: a descrição antecede a interpretação (slides 58 e 59)", "sub": ["Dado bruto: lesão única, castanha, de 8 mm, no dorso, borda irregular, aumento em 3 meses.", "Frase ideal: mácula pigmentada castanha, assimétrica, de 8 mm, com bordas irregulares, localizada no dorso, com crescimento referido recente; conduta: necessita avaliação dirigida.", "Erro comum: escrever 'nevo benigno' ou 'melanoma' antes do exame histopatológico; evite palavras vagas como 'rash', 'alergia' ou 'manchas pelo corpo'. Registre o dado físico imutável."]}, {"t": "Modelo de registro: anotação técnica (slide 61)", "sub": ["Lesão primária; características; arranjo e base; localização; sintomas e curso.", "Exemplo do slide: pápulas e pústulas, eritematosas e milimétricas, agrupadas sobre base eritematosa, em hemitórax direito (padrão dermatomérico), com hiperestesia local há 48 horas."]}, {"t": "Sistematização do exame tegumentar (slide 63)", "sub": ["1. Preparo: luz adequada, exposição progressiva e consentimento. 2. Inspeção: cor, lesões elementares, mucosas e anexos. 3. Palpação: relevo, textura, temperatura e testes. 4. Alertas: ABCDE e red flags (púrpura, necrose). 5. Registro: descrever a morfologia com precisão antes de inferir.", "Referências base do slide: Porto, Semiologia Médica, 8ª ed.; Bates, Propedêutica Médica, 12ª ed.; Rocco, Semiologia Médica, 2ª ed."]}]}], "glossario": [{"termo": "Mácula e mancha", "epônimo": "", "tecnica": "Inspeção e palpação", "definicao": "Mudança circunscrita de cor, sem relevo; mácula geralmente menor que 1 cm e mancha geralmente maior que 1 cm.", "slide": 24}, {"termo": "Vitropressão", "epônimo": "", "tecnica": "Lâmina de vidro sobre a lesão", "definicao": "Eritema vascular empalidece; púrpura (extravasamento de hemácias) não empalidece. Púrpura mais febre exige avaliação sistêmica imediata.", "slide": 26}, {"termo": "Pápula, placa e nódulo", "epônimo": "", "tecnica": "Palpação de tamanho, consistência e mobilidade", "definicao": "Pápula: pequena elevação (menor que 1 cm). Placa: extensão horizontal maior que a altura. Nódulo: componente palpável profundo.", "slide": 28}, {"termo": "Urtica", "epônimo": "", "tecnica": "Observação da duração de cada lesão", "definicao": "Elevação por edema dérmico, pruriginosa, que desaparece em menos de 24 horas; angioedema muda a prioridade.", "slide": 30}, {"termo": "Vesícula, bolha e pústula", "epônimo": "", "tecnica": "Medida em milímetros", "definicao": "Líquido seroso até 1 cm (vesícula), coleção maior (bolha) e exsudato purulento (pústula); o limiar varia entre os livros.", "slide": 32}, {"termo": "Escama e crosta", "epônimo": "", "tecnica": "Inspeção da superfície", "definicao": "Escama: desprendimento do estrato córneo. Crosta: exsudato ressecado.", "slide": 34}, {"termo": "Erosão, úlcera e fissura", "epônimo": "", "tecnica": "Estimativa da profundidade", "definicao": "Erosão: só epiderme. Úlcera: atinge derme ou subcutâneo e deixa cicatriz. Fissura: fenda linear, estreita e profunda.", "slide": 36}, {"termo": "Escoriação, liquenificação, atrofia e cicatriz", "epônimo": "", "tecnica": "Observação da evolução e do reparo", "definicao": "Coçadura linear, espessamento com sulcos acentuados, afinamento com pregueamento e reposição fibrótica.", "slide": 38}, {"termo": "Linhas de Beau", "epônimo": "Beau", "tecnica": "Inspeção da lâmina ungueal", "definicao": "Sulcos transversais da lâmina que indicam interrupção sistêmica do crescimento da unha.", "slide": 43}, {"termo": "Unhas de Terry", "epônimo": "Terry", "tecnica": "Inspeção do leito ungueal", "definicao": "Opacidade do leito ungueal associada a cirrose e hipoalbuminemia.", "slide": 43}, {"termo": "Unhas de Lindsay", "epônimo": "Lindsay", "tecnica": "Inspeção do leito ungueal", "definicao": "Alteração do leito ungueal associada à uremia.", "slide": 43}, {"termo": "Regra ABCDE", "epônimo": "", "tecnica": "Triagem de lesão pigmentada", "definicao": "Assimetria, bordas, cores, diâmetro (suspeito acima de 6 mm) e evolução; a evolução é o critério mais sensível.", "slide": 50}], "caso": {"titulo": "Manchas nas pernas e febre", "perfil": "Homem de 34 anos, sem uso de medicamentos de rotina, com manchas nas pernas e febre.", "etapas": [{"titulo": "Etapa 1 · Anamnese tegumentar", "texto": "Refere manchas nas pernas há 2 dias, que começaram nas panturrilhas e subiram. Febre de 38,9 °C, mal-estar e dor muscular. Nega prurido. Nega uso recente de medicamentos, produtos novos ou exposição solar intensa.", "perguntas": [{"pergunta": "Qual conjunto de dados da anamnese é mais importante para orientar a prioridade?", "alternativas": ["Prurido, uso de creme hidratante e exposição solar no último mês", "Início recente, febre associada e lesões novas nas pernas", "Hábito de caminhadas, sono irregular e preocupação com a aparência", "Histórico familiar de psoríase e uso de protetor solar diário", "Trabalho em escritório, sedentarismo e consumo de café em excesso"], "gabarito": "B", "justificativa": "Início recente, febre associada e progressão rápida mudam a prioridade. Essas perguntas da anamnese tegumentar orientam o alerta antes do exame da lesão.", "erradas": {"A": "Hidratante e exposição solar não mudam a prioridade neste contexto.", "C": "Hábitos e sono não têm relação direta com o alerta cutâneo.", "D": "Histórico de psoríase não explica febre e progressão rápida.", "E": "Hábitos gerais não definem a prioridade tegumentar."}}, {"pergunta": "Por que o médico pergunta sobre medicamentos e produtos novos nesta anamnese?", "alternativas": ["Para estimar o custo de exames complementares futuros", "Porque fármacos e produtos novos podem causar lesões graves", "Para confirmar alergia do paciente a alimentos da dieta", "Para avaliar se o paciente toma suplementos vitamínicos diários", "Porque toda lesão com febre é causada por medicamento"], "gabarito": "B", "justificativa": "Medicamentos e produtos novos são causas importantes de lesões cutâneas, algumas graves. A pergunta faz parte da anamnese tegumentar dirigida.", "erradas": {"A": "A pergunta não serve para cobrança de exames.", "C": "A alergia alimentar não é o foco da pergunta.", "D": "Suplementos não são o foco da pergunta.", "E": "Nem toda lesão com febre é medicamentosa."}}]}, {"titulo": "Etapa 2 · Descrição morfológica", "texto": "Exame: nas pernas, mais de dez lesões planas avermelhadas, de 2 a 6 mm, com bordas irregulares e sem elevação; algumas são puntiformes; não desaparecem quando a pele é pressionada.", "perguntas": [{"pergunta": "Qual é a descrição morfológica mais completa e correta?", "alternativas": ["Manchas vermelhas nas pernas, de aspecto alérgico e variadas", "Máculas purpúricas planas, múltiplas, de 2 a 6 mm", "Placas elevadas e pruriginosas nas pernas, bem delimitadas", "Vesículas agrupadas nas pernas, com base eritematosa", "Pápulas nodulares nas panturrilhas, com superfície escamosa"], "gabarito": "B", "justificativa": "A frase morfológica traz número, lesão predominante, medida, cor, relevo e localização. Aqui: múltiplas máculas planas, avermelhadas, de 2 a 6 mm, nas pernas, sem elevação.", "erradas": {"A": "Não tem número, medida nem relevo; 'aspecto de alergia' é interpretação, não descrição.", "C": "Placas elevadas e pruriginosas não descrevem lesões planas e não pruriginosas.", "D": "Vesículas têm conteúdo líquido e base eritematosa, o que não é o caso.", "E": "Pápulas nodulares com escama e crosta não são lesões planas."}}, {"pergunta": "Qual é o achado de 'não desaparecer à pressão' e o que ele indica?", "alternativas": ["Eritema, por vasodilatação intensa que não cede à compressão", "Púrpura, por extravasamento sanguíneo que não empalidece", "Urticária, por edema que se mantém após a compressão da pele", "Escoriação, por trauma que deixa a pele mais espessa", "Cicatriz, por tecido fibroso que não recupera a cor normal"], "gabarito": "B", "justificativa": "Eritema empalidece à compressão (vasodilatação). Lesão que não empalidece indica púrpura, por extravasamento sanguíneo. É preciso confirmar com a vitropressão.", "erradas": {"A": "Eritema empalidece à compressão; o achado é o oposto.", "C": "Urticária é elevada por edema, e o achado é de lesão plana.", "D": "Escoriação não é plana com coloração que não empalidece.", "E": "Cicatriz não é lesão de coloração recente como a descrita."}}]}, {"titulo": "Etapa 3 · Vitropressão", "texto": "A equipe aplica uma lâmina de vidro sobre algumas lesões. A coloração persiste sob a lâmina, sem empalidecer.", "perguntas": [{"pergunta": "Qual é a interpretação correta do resultado da vitropressão?", "alternativas": ["Eritema vascular, que empalidece quando a lâmina comprime a pele", "Púrpura, por extravasamento sanguíneo que não empalidece", "Lesão elevada, que só o toque palpatório poderia confirmar", "Escama, que não muda de cor sob pressão de qualquer tipo", "Cicatriz antiga, em que a cor não se altera com a pressão"], "gabarito": "B", "justificativa": "Se a coloração persiste sob a vitropressão, há extravasamento sanguíneo: púrpura, e não eritema. A vitropressão é o teste que confirma a diferença.", "erradas": {"A": "Eritema empalidece com a lâmina; aqui não empalideceu.", "C": "A vitropressão avalia cor à pressão, não elevação.", "D": "Escama não é plana com coloração de púrpura.", "E": "Cicatriz antiga não é o achado descrito."}}, {"pergunta": "Dentro das lesões que não empalidecem, qual é a descrição mais precisa para lesões puntiformes pequenas?", "alternativas": ["Equimose, por ser maior que 1 cm e de contorno irregular", "Petéquia, por ser pequena, puntiforme e sem elevação", "Vibice, por ser linear e formada por trauma muscular", "Telangiectasia, por ser vaso fino e visível em superfície", "Mácula hipocrômica, por ser mais clara que a pele vizinha"], "gabarito": "B", "justificativa": "Petéquia é lesão pequena, puntiforme e plana, que não empalidece. Equimose é maior, vibice é linear e telangiectasia é vascular e fina.", "erradas": {"A": "Equimose é maior, e não puntiforme.", "C": "Vibice é linear, de trauma muscular.", "D": "Telangiectasia é vaso fino, e não lesão puntiforme que não empalidece.", "E": "Mácula hipocrômica é mais clara, e o achado é de coloração que persiste."}}]}, {"titulo": "Etapa 4 · Estado geral e sinais de alerta", "texto": "Pressão arterial 105/65 mmHg; frequência cardíaca 118 bpm; temperatura 38,9 °C; paciente sonolento, com mal-estar importante. Não há dor intensa nem necrose.", "perguntas": [{"pergunta": "Qual é a classificação de prioridade adequada neste caso?", "alternativas": ["Ambulatorial, pois as lesões são pequenas e planas", "Avaliação urgente, com sinais vitais e estado geral", "Eletiva, após exames de rotina, pois não há dor associada", "Dispensável, pois a extensão é pequena e não há necrose", "Biópsia eletiva, sem avaliar os sinais vitais ao exame"], "gabarito": "B", "justificativa": "Púrpura com febre, taquicardia e estado geral alterado é alerta de avaliação urgente. A extensão pequena não tranquiliza: a sepse pode começar com lesões discretas.", "erradas": {"A": "Lesões pequenas não excluem gravidade quando há febre e estado geral alterado.", "C": "A ausência de dor não é critério para eletiva.", "D": "A ausência de necrose não exclui gravidade.", "E": "Biópsia não é a primeira conduta, e sinais vitais não podem ser deixados de lado."}}, {"pergunta": "Qual é a primeira conduta correta diante de púrpura com febre e sinais de instabilidade?", "alternativas": ["Medir e fotografar as lesões e agendar retorno em 15 dias", "Avaliação urgente, com sinais vitais e estado geral", "Prescrever anti-histamínico e liberar para casa com orientações", "Solicitar biópsia de pele antes de qualquer outra avaliação", "Iniciar corticoide oral, pois parecem vasculite alérgica"], "gabarito": "B", "justificativa": "Com púrpura, febre e instabilidade, a prioridade é avaliação urgente, com sinais vitais e estado geral, e tratamento conforme protocolo. Medir e fotografar são úteis, mas não substituem a avaliação urgente.", "erradas": {"A": "Retorno em 15 dias não é adequado diante do quadro.", "C": "Anti-histamínico não trata púrpura febril, e a alta é inadequada.", "D": "Biópsia não é a primeira conduta e não deve atrasar o tratamento.", "E": "Corticoide sem diagnóstico pode mascarar uma infecção grave."}}]}, {"titulo": "Etapa 5 · Registro e frase morfológica", "texto": "A equipe precisa registrar o exame no prontuário, de forma completa e reproduzível.", "perguntas": [{"pergunta": "Qual registro segue o modelo de campos recomendado na aula?", "alternativas": ["'Manchas nas pernas, feias, vermelhas, de tamanho pequeno, em paciente com febre'", "'Pernas, máculas purpúricas de 2 a 6 mm, planas, não empalidecem, com febre'", "'Paciente com doença de pele, lesões variadas na perna, melhora com repouso'", "'Lesão grande nas pernas, possivelmente alérgica, tratar com anti-histamínico'", "'Exame normal, sem alterações de pele, orientações gerais, retornar se necessário'"], "gabarito": "B", "justificativa": "O registro deve trazer localização, morfologia, medida, cor e limites, superfície, distribuição, sintomas e evolução, com vitropressão quando relevante. Só a alternativa B traz esses campos.", "erradas": {"A": "Termos subjetivos como 'feias' e sem medida não servem para registro.", "C": "Termos vagos como 'doença de pele' e 'melhora com repouso' não descrevem a lesão.", "D": "Interpretação ('possivelmente alérgica') antes da descrição não é registro adequado.", "E": "Exame normal não corresponde ao achado descrito."}}, {"pergunta": "Qual é a ordem correta de uma frase morfológica?", "alternativas": ["Localização, cor, número, medida e depois o diagnóstico presumido", "Número, lesão predominante, medida, cor, forma e limites, superfície e localização", "Diagnóstico, tratamento, medida e localização, para facilitar a conduta", "Cor, diagnóstico, número e evolução, em qualquer ordem, com avaliação incompleta", "Medida, diagnóstico, evolução e alergia, nessa sequência, sem reavaliação programada"], "gabarito": "B", "justificativa": "A frase morfológica segue a ordem: número, lesão predominante, medida, cor, forma e limites, superfície e localização. O diagnóstico vem depois da descrição.", "erradas": {"A": "Diagnóstico presumido não entra antes da descrição.", "C": "Tratamento não faz parte da frase morfológica.", "D": "A ordem é fixa, e diagnóstico não compõe a frase.", "E": "Alergia não faz parte da frase morfológica."}}]}, {"titulo": "Etapa 6 · Lesão pigmentada: a segunda queixa", "texto": "Outro paciente, 52 anos, procura consulta por uma lesão no dorso que está crescendo. Lesão única, castanha, de 8 mm, com borda irregular e cor variada. Há mudança nos últimos meses.", "perguntas": [{"pergunta": "Quais critérios ABCDE estão presentes nesta lesão?", "alternativas": ["Apenas o diâmetro, pois a lesão mede 8 mm e é única", "Bordas, cores, diâmetro acima de 6 mm e evolução", "Apenas a cor, pois lesões castanhas são sempre benignas", "Somente a evolução, sem relação com a forma ou a cor", "Nenhum, pois lesões de 8 mm são normais no dorso do paciente"], "gabarito": "B", "justificativa": "A lesão tem bordas irregulares (B), cores variadas (C), diâmetro de 8 mm, acima de 6 mm (D), e evolução (E). A assimetria (A) deve ser conferida no exame. A mudança importa, mesmo em lesões pequenas.", "erradas": {"A": "O diâmetro é um dos critérios, mas há outros presentes.", "C": "Cor castanha não garante benignidade; a cor variada é que pesa.", "D": "A evolução é um dos critérios, mas não é o único presente.", "E": "Lesões de 8 mm com bordas irregulares e evolução exigem avaliação."}}, {"pergunta": "Qual é a conduta mais adequada para esta lesão pigmentada em evolução?", "alternativas": ["Observação por 12 meses sem medida, pois lesões castanhas são comuns", "Medir, fotografar com escala e encaminhar para avaliação dirigida", "Aplicar creme clareador e reavaliar após 30 dias de uso local", "Prescrever antifúngico tópico, pois lesões escuras são infecciosas", "Tranquilizar o paciente, pelo tamanho menor que 1 cm da lesão"], "gabarito": "B", "justificativa": "Lesão pigmentada em evolução pede medir e fotografar com escala, comparar com as demais lesões e encaminhar para avaliação dirigida. Biópsia é decidida no contexto clínico.", "erradas": {"A": "Observação sem medida não é adequada em lesão em evolução.", "C": "Creme clareador não é conduta para lesão suspeita.", "D": "Antifúngico tópico não trata lesão pigmentada suspeita.", "E": "Tamanho não tranquiliza isoladamente."}}]}]}, "imagens": [{"slide": 1, "titulo": "Semiologia tegumentar", "explicacao": "Pele, mucosas, cabelos e unhas. Observar, palpar, descrever e contextualizar."}, {"slide": 5, "titulo": "O que o aluno deverá fazer", "explicacao": "Examinar com método, nomear a lesão predominante, descrever distribuição e evolução e reconhecer alertas."}, {"slide": 6, "titulo": "Anamnese tegumentar dirigida", "explicacao": "Quando começou, como mudou, prurido, dor, febre, novos medicamentos, produtos, sol e impacto na rotina."}, {"slide": 10, "titulo": "Inspeção e palpação", "explicacao": "Inspeção: cor, forma, extensão e superfície. Palpação: temperatura, consistência, mobilidade e dor. Só o tato confirma elevação."}, {"slide": 12, "titulo": "Pele geral: cor e circulação", "explicacao": "Palidez, eritema, cianose central e periférica, icterícia. Compare com o tom basal e observe mucosas e leitos ungueais."}, {"slide": 14, "titulo": "Pele geral: propriedades palpáveis", "explicacao": "Temperatura, textura, espessura, mobilidade, prega cutânea e turgor. Interpretar no contexto."}, {"slide": 16, "titulo": "A frase morfológica completa", "explicacao": "Número, lesão predominante, medida, cor, forma e limites, superfície e localização. Medir com régua."}, {"slide": 18, "titulo": "Distribuição e arranjo", "explicacao": "Localizada ou disseminada, simétrica ou assimétrica; linear, anular, agrupado, reticular ou em dermátomo."}, {"slide": 22, "titulo": "Primeira decisão: relevo e conteúdo", "explicacao": "Plana, elevada (sólida, edematosa ou líquida), ou com perda de superfície ou tecido. Procure a lesão predominante."}, {"slide": 25, "titulo": "Lesão plana: mácula ou mancha", "explicacao": "Mudança circunscrita de cor, sem elevação nem depressão. Hipercrômica, hipo ou acrômica. Descreva cor, medida e bordas."}, {"slide": 26, "titulo": "Compressão: eritema ou púrpura", "explicacao": "Vitropressão: eritema empalidece à compressão; púrpura não empalidece. Petéquia, púrpura, vibice e equimose."}, {"slide": 29, "titulo": "Lesões sólidas elevadas", "explicacao": "Pápula (pequena elevação), placa (extensão horizontal) e nódulo (componente profundo)."}, {"slide": 31, "titulo": "Elevação edematosa: urticas", "explicacao": "Urtica por edema, geralmente pruriginosa. Dermografismo. Lábios ou língua inchados mudam a prioridade."}, {"slide": 33, "titulo": "Conteúdo líquido: vesícula, bolha e pústula", "explicacao": "Vesícula (pequena), bolha (maior), pústula (conteúdo purulento). Registre a medida em milímetros."}, {"slide": 35, "titulo": "Superfície alterada: escama e crosta", "explicacao": "Escama (lâminas secas), crosta (exsudato ressecado). Descreva espessura, cor, aderência e extensão."}, {"slide": 37, "titulo": "Perda tecidual: erosão, úlcera e fissura", "explicacao": "Erosão: só epiderme. Úlcera: atinge a derme. Fissura: fenda linear."}, {"slide": 39, "titulo": "Alterações adicionais que contam a história", "explicacao": "Escoriação, liquenificação, cicatriz e atrofia. Pergunte se a alteração é primária ou secundária."}, {"slide": 42, "titulo": "Cabelos e couro cabeludo", "explicacao": "Rarefação em placa ou difusa; eritema, descamação, pústulas e cicatriz no couro cabeludo."}, {"slide": 44, "titulo": "Unhas: inspecione as dez", "explicacao": "Lâmina, leito e pregas. Faixa pigmentada, mancha branca, lâmina espessada, estriada ou descolada."}, {"slide": 46, "titulo": "Mucosas e regiões frequentemente omitidas", "explicacao": "Conjuntiva palpebral, lábios e língua, palmas e plantas, espaços interdigitais e dorso."}, {"slide": 49, "titulo": "Lesão pigmentada em evolução: ABCDE", "explicacao": "Assimetria, bordas, cores, diâmetro e evolução. A mudança importa, mesmo em lesões pequenas."}, {"slide": 53, "titulo": "Sinais de alerta tegumentares", "explicacao": "Púrpura com febre, bolhas extensas com mucosas, dor intensa, lesão pigmentada em evolução, dor desproporcional."}, {"slide": 55, "titulo": "Retorno ao caso: manchas e febre", "explicacao": "Lesões planas avermelhadas que não empalidecem, com febre e início recente. Descreva, avalie o estado geral e priorize."}, {"slide": 57, "titulo": "Exercício: descreva antes de diagnosticar", "explicacao": "Lesão única, castanha, 8 mm, de borda irregular, com evolução. Escreva a frase morfológica e a prioridade."}, {"slide": 60, "titulo": "Modelo de registro no prontuário", "explicacao": "Localização, morfologia, medida, cor e limites, superfície, distribuição, sintomas e evolução."}, {"slide": 62, "titulo": "Checklist de saída e referências", "explicacao": "História e contexto; exame completo; relevo e conteúdo; medida, distribuição e evolução; alertas e registro."}], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Lesão plana, avermelhada, que não empalidece à vitropressão com lâmina de vidro. Qual é a interpretação?", "alternativas": ["Púrpura, por extravasamento sanguíneo para a pele", "Eritema vascular, por vasodilatação reversível da derme", "Mácula hipercrômica, por aumento de melanina local", "Lesão telangiectásica, por dilatação de vasos finos", "Eritema por compressão, por isquemia transitória local"], "gabarito": "A", "justificativa": "Lesão que não empalidece indica extravasamento sanguíneo, característico de púrpura.", "epônimo": null, "tecnica": "Vitropressão", "slide": 26}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Na frase morfológica completa, após o número, qual é a ordem correta dos demais elementos?", "alternativas": ["Cor, lesão predominante, localização, medida, superfície, forma", "Lesão predominante, medida, cor, limites, superfície, localização", "Localização, lesão predominante, medida, cor, limites, superfície e forma", "Medida, cor, lesão predominante, localização, forma, superfície", "Superfície, lesão predominante, cor, medida, forma, localização"], "gabarito": "B", "justificativa": "A frase segue: número, lesão predominante, medida, cor, forma e limites, superfície e localização.", "epônimo": null, "tecnica": "Frase morfológica", "slide": 16}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Lesão sólida elevada, com componente palpável mais profundo, situado na derme profunda. Qual é o termo adequado?", "alternativas": ["Pápula, por elevação sólida de pequena extensão", "Placa, por extensão horizontal com descamação", "Nódulo, por componente palpável mais profundo", "Urtica, por elevação edematosa e pruriginosa", "Vesícula, por conteúdo líquido em cavidade"], "gabarito": "C", "justificativa": "Nódulo é o componente palpável mais profundo, com infiltrado na derme profunda.", "epônimo": null, "tecnica": "Nódulo", "slide": 29}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Lesão elevada por edema, pruriginosa, que muda de forma em poucas horas. Qual é o termo descritivo?", "alternativas": ["Vesícula, por conteúdo líquido claro e cavidade fina", "Pápula, por elevação sólida, fixa e de bordas nítidas", "Nódulo, por componente profundo e firme ao toque", "Urtica, por elevação edematosa, pruriginosa e fugaz", "Pústula, por conteúdo purulento, base inflamatória e halo"], "gabarito": "D", "justificativa": "Urtica é elevação por edema, geralmente pruriginosa; lábios ou língua inchados mudam a prioridade.", "epônimo": null, "tecnica": "Urtica", "slide": 31}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Lesão com lábios e língua inchados associada a urticas. Qual é a prioridade diante desse achado?", "alternativas": ["Registrar a medida das urticas e agendar retorno", "Descrever a cor das lesões antes de qualquer conduta", "Aplicar hidratante e reexaminar em uma semana", "Biópsia de pele de forma eletiva e ambulatorial", "Avaliar via aérea, pois há risco de angioedema"], "gabarito": "E", "justificativa": "Lábios ou língua inchados e falta de ar mudam a prioridade clínica para avaliação de via aérea.", "epônimo": null, "tecnica": "Angioedema", "slide": 31}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Crostas amareladas, de aspecto melicérico, aderidas à pele. O que representam?", "alternativas": ["Crosta, por exsudato ressecado aderido", "Escama, por desprendimento da camada córnea", "Liquenificação, por espessamento com sulcos", "Cicatriz, por reparo com tecido fibroso", "Escoriação, por trauma de coçadura superficial"], "gabarito": "A", "justificativa": "Crosta é exsudato ressecado aderido; escama é desprendimento de camada córnea, de lâminas soltas.", "epônimo": null, "tecnica": "Crosta", "slide": 35}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Perda tecidual que alcança a derme, com possível cicatriz residual. Qual é o termo correto?", "alternativas": ["Erosão, por perda restrita à epiderme", "Úlcera, por perda que atinge a derme", "Fissura, por solução de continuidade linear", "Escoriação, por trauma superficial recente", "Atrofia, por afinamento sem perda de tecido"], "gabarito": "B", "justificativa": "Úlcera atinge a derme e pode deixar cicatriz; erosão é restrita à epiderme.", "epônimo": null, "tecnica": "Úlcera", "slide": 37}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Pele fina e pregueada, sem histórico de coçadura, com cicatrizes de aspecto liso. Qual achado é mais provável?", "alternativas": ["Liquenificação, por espessamento e linhas acentuadas", "Escoriação, por trauma recente e crostoso", "Atrofia, por pele fina, pregueada e de aspecto liso", "Fissura, por perda linear de continuidade", "Erosão, por perda superficial da epiderme"], "gabarito": "C", "justificativa": "Atrofia cutânea é pele fina e pregueada, diferente da liquenificação, que é espessamento.", "epônimo": null, "tecnica": "Atrofia", "slide": 39}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Mácula ou pápula? Qual manobra confirma se há elevação da lesão?", "alternativas": ["Inspeção, com iluminação natural e distância de um metro", "Dermatoscopia, para medir a espessura do relevo", "Vitropressão, para confirmar cor e presença de relevo", "Palpação, para confirmar elevação e consistência", "Pesquisa de dermografismo, após atrito leve da pele"], "gabarito": "D", "justificativa": "Só a palpação confirma elevação; inspeção descreve cor e forma, mas não relevo.", "epônimo": null, "tecnica": "Palpação", "slide": 10}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Rarefação de cabelo em placa, com área redonda sem fios no couro cabeludo. Como descrever?", "alternativas": ["Rarefação difusa, na região frontal com fios finos", "Queda pela haste, com quebra de fios distais", "Descamação espessa, com placas no couro cabeludo", "Eritema com rarefação, em placas retroauriculares", "Rarefação em placa, com área redonda sem fios"], "gabarito": "E", "justificativa": "A descrição correta é rarefação em placa: área redonda sem fios, distinta da difusa.", "epônimo": null, "tecnica": "Cabelos", "slide": 42}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Ao examinar as unhas, qual é a recomendação de inspeção?", "alternativas": ["Inspecionar as dez unhas, quando possível, em mãos e pés", "Inspecionar apenas as unhas das mãos, por ser mais acessível", "Inspecionar apenas a unha com alteração visível", "Inspecionar somente a lâmina, sem leito e sem pregas", "Inspecionar apenas as unhas dos pés em pacientes idosos"], "gabarito": "A", "justificativa": "Deve-se inspecionar as dez unhas, quando possível, incluindo lâmina, leito e pregas, e comparar mãos e pés.", "epônimo": null, "tecnica": "Unhas", "slide": 44}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Quais áreas são frequentemente omitidas no exame tegumentar e devem ser examinadas?", "alternativas": ["Apenas face e antebraços, por serem expostos ao sol", "Conjuntivas, lábios, palmas, plantas e interdigitais", "Apenas couro cabeludo e região retroauricular, sem outras áreas", "Somente unhas e dobras inguinais, por serem áreas de risco", "Apenas dorso das mãos e tronco anterior, por serem visíveis"], "gabarito": "B", "justificativa": "O checklist inclui conjuntivas, cavidade oral acessível, lábios, palmas, plantas, espaços interdigitais e dorso.", "epônimo": null, "tecnica": "Mucosas", "slide": 46}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Lesão pigmentada com metades diferentes e variação de cor, que cresceu nos últimos meses. Qual é a prioridade?", "alternativas": ["Observação passiva por um ano, sem medir a lesão", "Tranquilizar, pois lesões pequenas não exigem exame", "Avaliação dirigida, com medida e foto de escala", "Corticoide tópico por duas semanas e reavaliação", "Remoção imediata sem avaliação dermatológica"], "gabarito": "C", "justificativa": "Lesão em evolução exige avaliação dirigida, medida e fotografia com escala; o tamanho não tranquiliza.", "epônimo": null, "tecnica": "ABCDE", "slide": 53}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Púrpura com febre e progressão rápida, em paciente com estado geral alterado. Qual é a conduta inicial?", "alternativas": ["Observação e retorno ambulatorial eletivo em quinze dias", "Corticoide tópico e reavaliação em duas semanas", "Analgesia simples e alta com orientação verbal", "Avaliação urgente, com sinais vitais e vitropressão", "Biópsia eletiva da lesão, sem avaliar o estado geral"], "gabarito": "D", "justificativa": "Púrpura com febre ou progressão rápida exige avaliação urgente, com sinais vitais e confirmação pela vitropressão.", "epônimo": null, "tecnica": "Alertas", "slide": 53}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Ao registrar uma lesão no prontuário, qual sequência de campos é a mais completa?", "alternativas": ["Cor, medida e nome da doença, sem distribuição nem sintomas", "Diagnóstico presumido, tratamento, alta e retorno ambulatorial", "Apenas morfologia e medida, sem localização nem evolução do quadro", "Sintomas, prescrição, tempo de internação e custo do exame", "Localização, morfologia, medida, cor, superfície e sintomas"], "gabarito": "E", "justificativa": "O modelo de registro inclui localização, morfologia, medida, cor, superfície e sintomas, entre outros campos.", "epônimo": null, "tecnica": "Registro", "slide": 60}], "manobras": [{"nome": "Palpação de temperatura e umidade", "epônimo": null, "como": "Dorso dos dedos, comparando lados e segmentos homólogos.", "alterado": "Assimetria de temperatura ou umidade.", "significado": "Alteração de perfusão ou de processo local; registre a região.", "slide": 10}, {"nome": "Prega cutânea (turgor)", "epônimo": null, "como": "Pince a pele do dorso da mão ou do abdome, solte e observe o retorno.", "alterado": "A prega persiste por mais tempo que o normal.", "significado": "Turgor diminuído, a interpretar no contexto: desidratação, idade e perda de peso.", "slide": 14}, {"nome": "Palpação de elevação", "epônimo": null, "como": "Passe a polpa do dedo sobre a lesão e compare com a pele vizinha.", "alterado": "Relevo palpável, com ou sem consistência sólida.", "significado": "Mácula (plana) versus pápula, placa ou nódulo (elevados). Só o tato confirma elevação.", "slide": 25}, {"nome": "Vitropressão", "epônimo": null, "como": "Aplique uma lâmina de vidro sobre a lesão avermelhada e observe a cor sob pressão.", "alterado": "A cor persiste sob a lâmina (não empalidece).", "significado": "Púrpura, por extravasamento sanguíneo. Se empalidece, é eritema, por vasodilatação.", "slide": 26}, {"nome": "Teste de atrito (dermografismo)", "epônimo": null, "como": "Risque a pele com um objeto romo, de forma leve, e observe a região após alguns minutos.", "alterado": "Urticas lineares no trajeto do atrito.", "significado": "Dermografismo: urticas após atrito. Forma de urticária; observe a duração das lesões.", "slide": 31}], "casos_extremos": [{"titulo": "Caso Y1 · Púrpura que não empalidece em paciente anticoagulado", "texto": "Mulher de 71 anos, em uso de varfarina com INR 3,8, apresenta há 2 dias manchas na face anterior das pernas, algumas em placas, que não empalidecem à vitropressão. Há febre baixa e perda de 4 kg em 1 mês. Plaquetas 140.000/mm³. Não há prurido.", "perguntas": [{"pergunta": "Qual é a interpretação semiológica mais precisa das lesões?", "alternativas": ["Eritema vascular, por vasodilatação reversível das arteríolas", "Telangiectasia, por dilatação persistente de vasos finos", "Púrpura, por extravasamento de hemácias para a derme", "Mácula hipocrômica, por perda localizada de melanina", "Vesícula hemorrágica, por conteúdo líquido em cavidade"], "gabarito": "C", "justificativa": "Lesões que não empalidecem indicam extravasamento sanguíneo; placas e equimoses são púrpura, mesmo com plaquetas preservadas."}, {"pergunta": "Qual é a prioridade diante da púrpura com febre e perda de peso neste contexto?", "alternativas": ["Avaliação urgente do estado geral, dos sinais vitais e da causa", "Ajuste do anticoagulante isolado, sem avaliação do estado geral", "Biópsia eletiva ambulatorial, agendada para quinze dias", "Corticoide tópico e reavaliação em uma semana de retorno", "Alta com orientação de compressão local e repouso domiciliar"], "gabarito": "A", "justificativa": "Púrpura com febre e perda de peso exige avaliação urgente e investigação sistêmica, além de reavaliar a anticoagulação."}]}, {"titulo": "Caso Y2 · Placa anular com borda ativa", "texto": "Homem de 40 anos, sem comorbidades, tem placa eritematosa única, anular, de 5 cm, com borda descamativa e centro discretamente hipocrômico, no dorso do punho, há 6 semanas. Refere jardinagem e contato com produtos de limpeza. Não há febre.", "perguntas": [{"pergunta": "Qual é a frase morfológica mais completa para esta lesão?", "alternativas": ["Nódulo firme, indolor, em região lombar, sem outras alterações", "Lesões múltiplas, purpúricas, em pápulas no antebraço, com prurido", "Mácula acastanhada, difusa, no tronco, sem medida definida", "Vesículas agrupadas em faixa unilateral no punho, com prurido", "Placa única, anular, eritematosa, de 5 cm, no dorso do punho"], "gabarito": "E", "justificativa": "A frase morfológica segue número, lesão predominante, medida, cor, forma e limites, superfície e localização."}, {"pergunta": "Qual é a conduta semiológica prioritária para documentar esta lesão antes de nomear a doença?", "alternativas": ["Registrar apenas o diagnóstico presumido no prontuário", "Coletar cultura de superfície sem descrever a morfologia da lesão", "Medir com régua, descrever distribuição e evolução", "Classificar como vesícula e reavaliar somente em um ano", "Anotar apenas a queixa de prurido sem descrever a morfologia"], "gabarito": "C", "justificativa": "A descrição morfológica, com medida e evolução, deve preceder a nomeação, e a fotografia com escala torna o registro verificável."}]}, {"titulo": "Caso Y3 · Mancha pigmentada em evolução com alteração ungueal", "texto": "Mulher de 52 anos apresenta mancha castanha de 9 mm no dorso do pé, com assimetria, bordas irregulares e cor variada, que cresceu nos últimos 4 meses. Há faixa pigmentada longitudinal em um dedo da mão, aparecida há 6 meses, com pigmento que se estende até a pele periungueal.", "perguntas": [{"pergunta": "Qual é a prioridade diagnóstica diante das duas lesões?", "alternativas": ["Observação das lesões por um ano, sem nenhum exame complementar", "Avaliação dermatológica dirigida da lesão e da faixa ungueal", "Tratamento antifúngico tópico por quatro semanas, sem avaliação", "Corticoide tópico em ambas as lesões, com reavaliação breve", "Alta com orientação de evitar exposição solar e retorno eletivo"], "gabarito": "B", "justificativa": "Lesão em evolução com critérios de malignidade e faixa ungueal que se estende à pele exigem avaliação dermatológica urgente."}, {"pergunta": "Ao examinar as unhas, qual é o procedimento correto que foi omitido?", "alternativas": ["Inspecionar apenas os dedos das mãos, por serem mais acessíveis", "Dispensar a inspeção ungueal em paciente com lesão cutânea visível", "Inspecionar somente a unha com alteração visível ao exame clínico", "Inspecionar apenas o leito ungueal, sem a lâmina da unha ou pregas", "Inspecionar as dez unhas, quando possível, comparando mãos e pés"], "gabarito": "E", "justificativa": "A inspeção ungueal completa inclui as dez unhas, comparação entre mãos e pés e exame de lâmina, leito e pregas."}]}]};
